 25	public class Main {
 26	    public static void main(String[] args) {
 27	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/loja");
 28	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 29	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 30	        String transLogUrl = System.getenv().getOrDefault("TRANSLOG_URL", "http://localhost:8081");
 31	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
 32	
 33	        Database database = new Database(dbUrl, dbUser, dbPassword);
 34	        database.initialize();
 35	
 36	        ProductRepository productRepository = new ProductRepositoryImpl(database);
 37	        productRepository.initializeCatalog();
 38	
 39	        OrderRepository orderRepository = new OrderRepositoryImpl(database);
 40	        CustomerRepository customerRepository = new CustomerRepositoryImpl(database);
 41	        NotificationRepository notificationRepository = new NotificationRepositoryImpl(database);
 42	
 43	        TransLogClient transLogClient = new TransLogClient(transLogUrl);
 44	
 45	        Map<ShippingMethod, ShippingStrategy> shippingStrategies = Map.of(
 46	                ShippingMethod.ECONOMY, new EconomyShipping(transLogClient),
 47	                ShippingMethod.EXPRESS, new ExpressShipping(transLogClient),
 48	                ShippingMethod.STORE_PICKUP, new StorePickupShipping(),
 49	                ShippingMethod.COURIER, new CourierShipping()
 50	        );
 51	
 52	        Map<CouponCode, CouponStrategy> couponStrategies = Map.of(
 53	                CouponCode.WELCOME10, new Welcome10Coupon(orderRepository),
 54	                CouponCode.MINUS50, new Minus50Coupon(),
 55	                CouponCode.FREESHIPPING, new FreeShippingCoupon(),
 56	                CouponCode.BUY3PAY2, new Buy3Pay2Coupon(productRepository)
 57	        );
 58	
 59	        Map<ClubTier, ClubTierStrategy> clubTierStrategies = Map.of(
 60	                ClubTier.BRONZE, new BronzeTier(),
 61	                ClubTier.SILVER, new SilverTier(),
 62	                ClubTier.GOLD, new GoldTier()
 63	        );
 64	
 65	        Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies = Map.of(
 66	                PaymentMethod.PIX, new PixPayment(),
 67	                PaymentMethod.CREDIT_CARD, new CreditCardPayment(),
 68	                PaymentMethod.BANK_SLIP, new BankSlipPayment()
 69	        );
 70	
 71	        List<PaymentConfirmedObserver> paymentObservers = List.of(
 72	                new StockObserver(productRepository),
 73	                new CreditObserver(customerRepository),
 74	                new NotificationObserver(notificationRepository)
 75	        );
 76	
 77	        CheckoutService checkoutService = new CheckoutService(
 78	                productRepository,
 79	                shippingStrategies,
 80	                couponStrategies,
 81	                clubTierStrategies,
 82	                paymentMethodStrategies
 83	        );
 84	
 85	        OrderService orderService = new OrderService(
 86	                orderRepository,
 87	                customerRepository,
 88	                notificationRepository,
 89	                productRepository,
 90	                paymentObservers
 91	        );
 92	
 93	        ValidationService validationService = new ValidationService(
 94	                productRepository,
 95	                orderRepository,
 96	                shippingStrategies,
 97	                couponStrategies,
 98	                paymentMethodStrategies
 99	        );
100	
101	        ApiController apiController = new ApiController(
102	                checkoutService,
