117	package com.loja.services;
118	
119	import com.loja.domain.entities.*;
120	import com.loja.domain.strategies.club.ClubTierStrategy;
121	import com.loja.domain.strategies.coupon.CouponStrategy;
122	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
123	import com.loja.domain.strategies.shipping.ShippingStrategy;
124	import com.loja.domain.strategies.shipping.ShippingUnavailableException;
125	import com.loja.repositories.ProductRepository;
126	
127	import java.util.List;
128	import java.util.Map;
129	
130	public class CheckoutService {
131	    private static final double MAX_COUPON_DISCOUNT_PERCENT = 0.30;
132	
133	    private final ProductRepository productRepository;
134	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
135	    private final Map<CouponCode, CouponStrategy> couponStrategies;
136	    private final Map<ClubTier, ClubTierStrategy> clubTierStrategies;
137	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
138	
139	    public CheckoutService(
140	            ProductRepository productRepository,
141	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
142	            Map<CouponCode, CouponStrategy> couponStrategies,
143	            Map<ClubTier, ClubTierStrategy> clubTierStrategies,
144	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
145	        this.productRepository = productRepository;
146	        this.shippingStrategies = shippingStrategies;
147	        this.couponStrategies = couponStrategies;
148	        this.clubTierStrategies = clubTierStrategies;
149	        this.paymentMethodStrategies = paymentMethodStrategies;
150	    }
151	
152	    public OrderSummary calculateSummary(CheckoutRequest request) throws ShippingUnavailableException {
153	        Money productsSubtotal = calculateProductsSubtotal(request.items());
154	
155	        ShippingStrategy shippingStrategy = shippingStrategies.get(request.shippingMethod());
156	        Money rawShippingCost = shippingStrategy.calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
157	        int baseDeliveryDays = shippingStrategy.calculateDeliveryDays(request.region());
158	
159	        CouponStrategy couponStrategy = request.coupon() != null ? couponStrategies.get(request.coupon()) : null;
160	        Money couponDiscount = Money.zero();
161	        if (couponStrategy != null) {
162	            couponDiscount = couponStrategy.calculateDiscount(
163	                    productsSubtotal,
164	                    rawShippingCost,
165	                    request.items(),
166	                    request.customerCpf()
167	            );
168	            Money maxDiscount = productsSubtotal.multiply(MAX_COUPON_DISCOUNT_PERCENT);
169	            if (couponDiscount.isGreaterThan(maxDiscount)) {
170	                couponDiscount = maxDiscount;
171	            }
172	        }
173	
174	        Money insurance = calculateInsurance(productsSubtotal, request.region());
175	
176	        ClubTierStrategy clubStrategy = clubTierStrategies.get(request.clubTier());
177	        Money adjustedShippingCost = clubStrategy.adjustShippingCost(rawShippingCost, request.shippingMethod());
178	
179	        Money orderTotal = productsSubtotal
180	                .subtract(couponDiscount)
181	                .add(adjustedShippingCost)
182	                .add(insurance);
183	
184	        PaymentMethodStrategy paymentStrategy = paymentMethodStrategies.get(request.paymentMethod());
185	        int installments = paymentStrategy.calculateInstallments(request.installments());
186	        Money paymentAdjustment = paymentStrategy.calculateAdjustment(
187	                orderTotal,
188	                installments,
189	                request.coupon() != null
190	        );
191	
192	        Money finalTotal = orderTotal.add(paymentAdjustment);
193	        Money installmentAmount = paymentStrategy.calculateInstallmentAmount(finalTotal, installments);
194	
195	        Money nextPurchaseCredit = clubStrategy.calculateCredit(productsSubtotal);
196	        boolean gift = clubStrategy.hasGift(productsSubtotal);
197	
198	        return new OrderSummary(
199	                productsSubtotal,
200	                couponDiscount,
201	                adjustedShippingCost,
202	                baseDeliveryDays,
203	                insurance,
204	                paymentAdjustment,
205	                finalTotal,
206	                installments,
207	                installmentAmount,
208	                nextPurchaseCredit,
209	                gift
210	        );
211	    }
212	
213	    private Money calculateProductsSubtotal(List<OrderItem> items) {
214	        Money subtotal = Money.zero();
215	        for (OrderItem item : items) {
216	            Product product = productRepository.findBySku(item.getSku());
217	            Money itemTotal = product.getPrice().multiply(item.getQuantity());
218	            subtotal = subtotal.add(itemTotal);
219	        }
220	        return subtotal;
221	    }
222	
223	    private double calculateTotalWeight(List<OrderItem> items) {
224	        double totalWeight = 0;
225	        for (OrderItem item : items) {
226	            Product product = productRepository.findBySku(item.getSku());
227	            totalWeight += product.getWeightKg() * item.getQuantity();
228	        }
229	        return totalWeight;
230	    }
231	
232	    private Money calculateInsurance(Money productsSubtotal, Region region) {
233	        double percentage = switch (region) {
234	            case SOUTHEAST, SOUTH -> 0.01;
235	            case MIDWEST -> 0.015;
236	            case NORTHEAST -> 0.02;
237	            case NORTH -> 0.025;
238	        };
239	
240	        Money insurance = productsSubtotal.multiply(percentage);
241	
242	        Money limit = switch (region) {
243	            case NORTH, NORTHEAST -> Money.of(30.00);
244	            case SOUTHEAST, SOUTH, MIDWEST -> null;
245	        };
246	
247	        if (limit != null && insurance.isGreaterThan(limit)) {
248	            return limit;
249	        }
250	
251	        return insurance;
252	    }
253	
254	    public record CheckoutRequest(
255	            String customerCpf,
256	            List<OrderItem> items,
257	            String zipCode,
258	            Region region,
259	            ShippingMethod shippingMethod,
260	            CouponCode coupon,
261	            PaymentMethod paymentMethod,
262	            int installments,
263	            ClubTier clubTier
264	    ) {
265	    }
266	}

