 27	package com.loja.domain.strategies.club;
 28	
 29	import com.loja.domain.entities.*;
 30	
 31	public interface ClubTierStrategy {
 32	    Money calculateCredit(Money productsSubtotal);
 33	
 34	    Money adjustShippingCost(Money shippingCost, ShippingMethod shippingMethod);
 35	
 36	    boolean hasGift(Money productsSubtotal);
 37	
 38	    ClubTier getTier();
 39	}
 40	package com.loja.domain.strategies.club;
 41	
 42	import com.loja.domain.entities.*;
 43	
 44	public class GoldTier implements ClubTierStrategy {
 45	    private static final Money GIFT_THRESHOLD = Money.of(500.00);
 46	
 47	    @Override
 48	    public Money calculateCredit(Money productsSubtotal) {
 49	        return productsSubtotal.multiply(0.05);
 50	    }
 51	
 52	    @Override
 53	    public Money adjustShippingCost(Money shippingCost, ShippingMethod shippingMethod) {
 54	        if (shippingMethod == ShippingMethod.COURIER) {
 55	            return shippingCost;
 56	        }
 57	        return Money.zero();
 58	    }
 59	
 60	    @Override
 61	    public boolean hasGift(Money productsSubtotal) {
 62	        return productsSubtotal.isGreaterThan(GIFT_THRESHOLD);
 63	    }
 64	
