279	import java.math.BigDecimal;
280	import java.math.RoundingMode;
281	
282	public class CreditCardPayment implements PaymentMethodStrategy {
283	    private static final double MONTHLY_INTEREST_RATE = 0.0199;
284	    private static final int MAX_INSTALLMENTS_NO_INTEREST = 3;
285	    private static final int MAX_INSTALLMENTS = 12;
286	
287	    @Override
288	    public Money calculateAdjustment(Money orderTotal, int installments, boolean hasCoupon) {
289	        if (installments <= MAX_INSTALLMENTS_NO_INTEREST) {
290	            return Money.zero();
291	        }
292	
293	        Money installmentAmount = calculateInstallmentWithInterest(orderTotal, installments);
294	        Money finalTotal = installmentAmount.multiply(installments);
295	        return finalTotal.subtract(orderTotal);
296	    }
297	
298	    @Override
299	    public int calculateInstallments(int requestedInstallments) {
300	        if (requestedInstallments < 1) {
301	            return 1;
302	        }
303	        if (requestedInstallments > MAX_INSTALLMENTS) {
304	            return MAX_INSTALLMENTS;
305	        }
306	        return requestedInstallments;
307	    }
308	
309	    @Override
310	    public Money calculateInstallmentAmount(Money finalTotal, int installments) {
311	        return finalTotal.divide(installments);
312	    }
313	
314	    private Money calculateInstallmentWithInterest(Money principal, int installments) {
315	        BigDecimal rate = BigDecimal.valueOf(MONTHLY_INTEREST_RATE);
316	        BigDecimal numInstallments = BigDecimal.valueOf(installments);
317	
318	        BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
319	        BigDecimal denominator = BigDecimal.ONE.subtract(
320	                onePlusRate.pow(-installments, new java.math.MathContext(10, RoundingMode.HALF_EVEN))
321	        );
322	
323	        BigDecimal installment = principal.toBigDecimal()
324	                .multiply(rate)
325	                .divide(denominator, 2, RoundingMode.HALF_EVEN);
326	
327	        return Money.of(installment);
328	    }
329	
330	
331	    @Override
332	    public boolean isAvailable(Money orderTotal) {
333	        return true;
334	    }
335	
336	    @Override
337	    public PaymentMethod getMethod() {
338	        return PaymentMethod.CREDIT_CARD;
339	    }
340	}
