209	package com.loja.infrastructure;
210	
211	import com.google.gson.Gson;
212	import com.google.gson.JsonObject;
213	
214	import java.io.IOException;
215	import java.net.URI;
216	import java.net.http.HttpClient;
217	import java.net.http.HttpRequest;
218	import java.net.http.HttpResponse;
219	import java.time.Duration;
220	
221	public class TransLogClient {
222	    private final String baseUrl;
223	    private final HttpClient httpClient;
224	    private final Gson gson;
225	
226	    public TransLogClient(String baseUrl) {
227	        this.baseUrl = baseUrl;
228	        this.httpClient = HttpClient.newBuilder()
229	                .connectTimeout(Duration.ofSeconds(2))
230	                .build();
231	        this.gson = new Gson();
232	    }
233	
234	    public TransLogQuote getQuote(String zipCode, double weightKg, TransLogService service) throws TransLogException {
235	        int weightG = (int) (weightKg * 1000);
236	        String serviceCode = service == TransLogService.ECONOMY ? "STD" : "EXP";
237	
238	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
239	                baseUrl, zipCode, weightG, serviceCode);
240	
241	        HttpRequest request = HttpRequest.newBuilder()
242	                .uri(URI.create(url))
243	                .timeout(Duration.ofSeconds(2))
244	                .GET()
245	                .build();
246	
247	        try {
248	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
249	
250	            if (response.statusCode() != 200) {
251	                throw new TransLogException("TransLog returned status " + response.statusCode());
252	            }
253	
254	            JsonObject json = gson.fromJson(response.body(), JsonObject.class);
255	
256	            if (json.has("error")) {
257	                String error = json.get("error").getAsString();
258	                if ("ZIP_NOT_SERVED".equals(error)) {
259	                    throw new ZipNotServedException("ZIP not served by TransLog");
260	                }
261	                throw new TransLogException("TransLog error: " + error);
262	            }
263	
264	            int priceCents = json.get("price_cents").getAsInt();
265	            int etaHours = json.get("eta_hours").getAsInt();
266	
267	            return new TransLogQuote(priceCents, etaHours);
268	
269	        } catch (IOException | InterruptedException e) {
270	            throw new TransLogException("Failed to connect to TransLog", e);
271	        }
272	    }
273	
274	    public enum TransLogService {
275	        ECONOMY,
276	        EXPRESS
277	    }
278	
279	    public static class TransLogQuote {
280	        private final int priceCents;
281	        private final int etaHours;
282	
283	        public TransLogQuote(int priceCents, int etaHours) {
284	            this.priceCents = priceCents;
285	            this.etaHours = etaHours;
286	        }
287	
288	        public double getPriceReais() {
289	            return priceCents / 100.0;
290	        }
291	
292	        public int getDeliveryDays() {
293	            return (int) Math.ceil(etaHours / 24.0);
294	        }
295	    }
296	
297	    public static class TransLogException extends Exception {
298	        public TransLogException(String message) {
299	            super(message);
300	        }
301	
302	        public TransLogException(String message, Throwable cause) {
303	            super(message, cause);
304	        }
305	    }
306	
307	    public static class ZipNotServedException extends TransLogException {
308	        public ZipNotServedException(String message) {
309	            super(message);
310	        }
311	    }
312	}
