  2	
  3	import com.loja.domain.entities.*;
  4	import com.loja.domain.strategies.coupon.CouponStrategy;
  5	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
  6	import com.loja.domain.strategies.shipping.ShippingStrategy;
  7	import com.loja.repositories.OrderRepository;
