  9	
 10	import java.util.HashSet;
 11	import java.util.List;
 12	import java.util.Map;
 13	import java.util.Set;
 14	
 15	public class ValidationService {
 16	    private final ProductRepository productRepository;
 17	    private final OrderRepository orderRepository;
 18	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
 19	    private final Map<CouponCode, CouponStrategy> couponStrategies;
 20	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
 21	
 22	    public ValidationService(
 23	            ProductRepository productRepository,
 24	            OrderRepository orderRepository,
 25	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
 26	            Map<CouponCode, CouponStrategy> couponStrategies,
 27	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
 28	        this.productRepository = productRepository;
 29	        this.orderRepository = orderRepository;
 30	        this.shippingStrategies = shippingStrategies;
 31	        this.couponStrategies = couponStrategies;
 32	        this.paymentMethodStrategies = paymentMethodStrategies;
 33	    }
 34	
 35	    public void validateCheckoutRequest(CheckoutService.CheckoutRequest request) throws ValidationException {
 36	        validateOrderStructure(request);
 37	        validateProducts(request.items());
 38	        validateClubTier(request.clubTier());
 39	        validateRegion(request.region());
 40	        validateZipCode(request.zipCode());
 41	        validateShippingMethod(request.shippingMethod(), request.items(), request.zipCode());
 42	        validateCoupon(request);
 43	        validatePaymentMethod(request);
 44	    }
 45	
 46	    private void validateOrderStructure(CheckoutService.CheckoutRequest request) throws ValidationException {
 47	        if (request.items() == null || request.items().isEmpty()) {
 48	            throw new ValidationException("INVALID_ORDER", "Cart is empty");
 49	        }
 50	
 51	        if (request.customerCpf() == null || request.customerCpf().isBlank()) {
 52	            throw new ValidationException("INVALID_ORDER", "Customer CPF is required");
 53	        }
 54	
 55	        Set<String> skus = new HashSet<>();
 56	        for (OrderItem item : request.items()) {
 57	            if (item.getSku() == null || item.getSku().isBlank()) {
 58	                throw new ValidationException("INVALID_ORDER", "Item SKU is required");
 59	            }
 60	
 61	            if (item.getQuantity() <= 0) {
 62	                throw new ValidationException("INVALID_ORDER", "Item quantity must be positive");
 63	            }
 64	
 65	            if (skus.contains(item.getSku())) {
 66	                throw new ValidationException("INVALID_ORDER", "Duplicate SKU in cart: " + item.getSku());
 67	            }
 68	            skus.add(item.getSku());
 69	        }
 70	    }
 71	
 72	    private void validateProducts(List<OrderItem> items) throws ValidationException {
 73	        for (OrderItem item : items) {
 74	            Product product = productRepository.findBySku(item.getSku());
 75	
 76	            if (product == null) {
 77	                throw new ValidationException("UNKNOWN_PRODUCT", "Product not found: " + item.getSku());
 78	            }
 79	
 80	            if (product.isDiscontinued()) {
 81	                throw new ValidationException("PRODUCT_DISCONTINUED", "Product discontinued: " + item.getSku());
 82	            }
 83	
 84	            if (!product.hasStock(item.getQuantity())) {
 85	                throw new ValidationException("INSUFFICIENT_STOCK", "Insufficient stock for product: " + item.getSku());
 86	            }
 87	        }
 88	    }
 89	
 90	    private void validateClubTier(ClubTier clubTier) throws ValidationException {
 91	        if (clubTier == null) {
 92	            throw new ValidationException("INVALID_CLUB_TIER", "Club tier is required");
 93	        }
 94	    }
 95	
 96	    private void validateRegion(Region region) throws ValidationException {
 97	        if (region == null) {
 98	            throw new ValidationException("INVALID_REGION", "Region is required");
 99	        }
100	    }
101	
102	    private void validateZipCode(String zipCode) throws ValidationException {
103	        if (zipCode == null || !zipCode.matches("\\d{8}")) {
104	            throw new ValidationException("INVALID_ZIP_CODE", "Invalid ZIP code format");
105	        }
106	    }
107	
108	    private void validateShippingMethod(ShippingMethod shippingMethod, List<OrderItem> items, String zipCode) throws ValidationException {
109	        if (shippingMethod == null) {
110	            throw new ValidationException("INVALID_SHIPPING_METHOD", "Shipping method is required");
111	        }
112	
113	        ShippingStrategy strategy = shippingStrategies.get(shippingMethod);
114	        if (strategy == null) {
115	            throw new ValidationException("INVALID_SHIPPING_METHOD", "Invalid shipping method");
116	        }
117	
118	        double totalWeight = calculateTotalWeight(items);
119	
120	        try {
121	            Money cost = strategy.calculateCost(zipCode, totalWeight);
122	            if (!strategy.isAvailable(totalWeight, zipCode)) {
123	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available");
124	            }
125	        } catch (Exception e) {
126	            if (e.getMessage() != null && e.getMessage().contains("unavailable")) {
127	                throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
128	            }
129	            if (e.getMessage() != null && e.getMessage().contains("not served")) {
130	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available for this location");
131	            }
132	            throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
133	        }
134	    }
135	
136	    private void validateCoupon(CheckoutService.CheckoutRequest request) throws ValidationException {
137	        if (request.coupon() == null) {
138	            return;
139	        }
140	
141	        CouponStrategy strategy = couponStrategies.get(request.coupon());
142	        if (strategy == null) {
143	            throw new ValidationException("INVALID_COUPON", "Invalid coupon code");
144	        }
145	
146	        Money productsSubtotal = calculateProductsSubtotal(request.items());
147	        Money shippingCost = Money.zero();
148	        try {
149	            shippingCost = shippingStrategies.get(request.shippingMethod())
150	                    .calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
151	        } catch (Exception e) {
152	        }
153	
154	        if (!strategy.isApplicable(
155	                productsSubtotal,
156	                shippingCost,
157	                request.items(),
158	                request.customerCpf(),
159	                request.shippingMethod())) {
160	            throw new ValidationException("COUPON_NOT_APPLICABLE", "Coupon not applicable to this order");
161	        }
162	    }
163	
164	    private void validatePaymentMethod(CheckoutService.CheckoutRequest request) throws ValidationException {
165	        if (request.paymentMethod() == null) {
166	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Payment method is required");
167	        }
168	
169	        PaymentMethodStrategy strategy = paymentMethodStrategies.get(request.paymentMethod());
170	        if (strategy == null) {
171	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Invalid payment method");
172	        }
173	
174	        int installments = request.installments();
175	        if (request.paymentMethod() == PaymentMethod.PIX || request.paymentMethod() == PaymentMethod.BANK_SLIP) {
176	            if (installments != 1 && installments != 0) {
177	                throw new ValidationException("INVALID_INSTALLMENTS", "PIX and bank slip must be paid in full");
178	            }
179	        } else if (request.paymentMethod() == PaymentMethod.CREDIT_CARD) {
180	            if (installments < 1 || installments > 12) {
181	                throw new ValidationException("INVALID_INSTALLMENTS", "Credit card installments must be between 1 and 12");
182	            }
183	        }
184	
185	        Money productsSubtotal = calculateProductsSubtotal(request.items());
186	        if (!strategy.isAvailable(productsSubtotal)) {
187	            throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE", "Payment method not available for this order total");
188	        }
189	    }
190	
191	    private Money calculateProductsSubtotal(List<OrderItem> items) {
192	        Money subtotal = Money.zero();
193	        for (OrderItem item : items) {
194	            Product product = productRepository.findBySku(item.getSku());
195	            subtotal = subtotal.add(product.getPrice().multiply(item.getQuantity()));
196	        }
197	        return subtotal;
198	    }
199	
200	    private double calculateTotalWeight(List<OrderItem> items) {
201	        double totalWeight = 0;
202	        for (OrderItem item : items) {
203	            Product product = productRepository.findBySku(item.getSku());
204	            totalWeight += product.getWeightKg() * item.getQuantity();
205	        }
206	        return totalWeight;
207	    }
208	
209	    public static class ValidationException extends Exception {
210	        private final String errorCode;
211	
212	        public ValidationException(String errorCode, String message) {
213	            super(message);
214	            this.errorCode = errorCode;
215	        }
216	
217	        public String getErrorCode() {
218	            return errorCode;
219	        }
220	    }
221	}

