 46	    private void validateOrderStructure(CheckoutService.CheckoutRequest request) throws ValidationException {
 47	        if (request.items() == null || request.items().isEmpty()) {
 48	            throw new ValidationException("INVALID_ORDER", "Cart is empty");
 49	        }
 50	
 51	        if (request.customerCpf() == null || request.customerCpf().isBlank()) {
 52	            throw new ValidationException("INVALID_ORDER", "Customer CPF is required");
 53	        }
 54	
 55	        Set<String> skus = new HashSet<>();
 56	        for (OrderItem item : request.items()) {
 57	            if (item.getSku() == null || item.getSku().isBlank()) {
 58	                throw new ValidationException("INVALID_ORDER", "Item SKU is required");
 59	            }
 60	
 61	            if (item.getQuantity() <= 0) {
 62	                throw new ValidationException("INVALID_ORDER", "Item quantity must be positive");
 63	            }
 64	
 65	            if (skus.contains(item.getSku())) {
 66	                throw new ValidationException("INVALID_ORDER", "Duplicate SKU in cart: " + item.getSku());
 67	            }
 68	            skus.add(item.getSku());
 69	        }
 70	    }
 71	
 72	    private void validateProducts(List<OrderItem> items) throws ValidationException {
 73	        for (OrderItem item : items) {
 74	            Product product = productRepository.findBySku(item.getSku());
 75	
 76	            if (product == null) {
 77	                throw new ValidationException("UNKNOWN_PRODUCT", "Product not found: " + item.getSku());
 78	            }
 79	
 80	            if (product.isDiscontinued()) {
 81	                throw new ValidationException("PRODUCT_DISCONTINUED", "Product discontinued: " + item.getSku());
 82	            }
 83	
 84	            if (!product.hasStock(item.getQuantity())) {
 85	                throw new ValidationException("INSUFFICIENT_STOCK", "Insufficient stock for product: " + item.getSku());
 86	            }
 87	        }
 88	    }
