136	    private void validateCoupon(CheckoutService.CheckoutRequest request) throws ValidationException {
137	        if (request.coupon() == null) {
138	            return;
139	        }
140	
141	        CouponStrategy strategy = couponStrategies.get(request.coupon());
142	        if (strategy == null) {
143	            throw new ValidationException("INVALID_COUPON", "Invalid coupon code");
144	        }
145	
146	        Money productsSubtotal = calculateProductsSubtotal(request.items());
147	        Money shippingCost = Money.zero();
148	        try {
149	            shippingCost = shippingStrategies.get(request.shippingMethod())
150	                    .calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
151	        } catch (Exception e) {
152	        }
153	
154	        if (!strategy.isApplicable(
155	                productsSubtotal,
156	                shippingCost,
157	                request.items(),
158	                request.customerCpf(),
159	                request.shippingMethod())) {
160	            throw new ValidationException("COUPON_NOT_APPLICABLE", "Coupon not applicable to this order");
161	        }
162	    }
163	
164	    private void validatePaymentMethod(CheckoutService.CheckoutRequest request) throws ValidationException {
165	        if (request.paymentMethod() == null) {
166	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Payment method is required");
167	        }
168	
169	        PaymentMethodStrategy strategy = paymentMethodStrategies.get(request.paymentMethod());
170	        if (strategy == null) {
171	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Invalid payment method");
172	        }
173	
174	        int installments = request.installments();
175	        if (request.paymentMethod() == PaymentMethod.PIX || request.paymentMethod() == PaymentMethod.BANK_SLIP) {
176	            if (installments != 1 && installments != 0) {
177	                throw new ValidationException("INVALID_INSTALLMENTS", "PIX and bank slip must be paid in full");
178	            }
179	        } else if (request.paymentMethod() == PaymentMethod.CREDIT_CARD) {
180	            if (installments < 1 || installments > 12) {
181	                throw new ValidationException("INVALID_INSTALLMENTS", "Credit card installments must be between 1 and 12");
182	            }
183	        }
184	
185	        Money productsSubtotal = calculateProductsSubtotal(request.items());
186	        if (!strategy.isAvailable(productsSubtotal)) {
187	            throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE", "Payment method not available for this order total");
188	        }
189	    }
