200	    private double calculateTotalWeight(List<OrderItem> items) {
201	        double totalWeight = 0;
202	        for (OrderItem item : items) {
203	            Product product = productRepository.findBySku(item.getSku());
204	            totalWeight += product.getWeightKg() * item.getQuantity();
205	        }
206	        return totalWeight;
207	    }
