        OrderResponseDto dto = new OrderResponseDto();
        dto.id = order.getId();
        dto.status = order.getStatus().name();
        dto.createdAt = DateTimeFormatter.ISO_INSTANT.format(order.getCreatedAt());
        dto.summary = toSummaryDto(order.getSummary());
